package java.util;
public class Properties extends Hashtable<Object,Object> {protected Properties defaults;public Properties(){this(null);}public Properties(Properties defaults){this.defaults=defaults;}public synchronized Object setProperty(String key,String value){return put(key,value);}public String getProperty(String key){Object v=get(key);String s=v instanceof String?(String)v:null;return s==null&&defaults!=null?defaults.getProperty(key):s;}public String getProperty(String key,String defaultValue){String v=getProperty(key);return v==null?defaultValue:v;}public Enumeration<?> propertyNames(){HashSet<Object> s=new HashSet<Object>();names(s);return Collections.enumeration(s);}private void names(Set<Object> s){if(defaults!=null)defaults.names(s);for(Object k:keySet())s.add((String)k);}public Set<String> stringPropertyNames(){HashSet<String> s=new HashSet<String>();stringNames(s);return s;}private void stringNames(Set<String> s){if(defaults!=null)defaults.stringNames(s);for(Map.Entry<Object,Object> e:entrySet())if(e.getKey() instanceof String&&e.getValue() instanceof String)s.add((String)e.getKey());}public synchronized void load(java.io.InputStream in) throws java.io.IOException {StringBuilder line=new StringBuilder();int c;while((c=in.read())!=-1){if(c=='\n'||c=='\r'){parse(line.toString());line=new StringBuilder();}else line.append((char)c);}if(line.length()>0)parse(line.toString());}private void parse(String line){int i=0,n=line.length();while(i<n&&Character.isWhitespace(line.charAt(i)))i++;if(i==n||line.charAt(i)=='#'||line.charAt(i)=='!')return;int start=i;while(i<n&&line.charAt(i)!='='&&line.charAt(i)!=':'&&!Character.isWhitespace(line.charAt(i)))i++;String key=line.substring(start,i);while(i<n&&Character.isWhitespace(line.charAt(i)))i++;if(i<n&&(line.charAt(i)=='='||line.charAt(i)==':'))i++;while(i<n&&Character.isWhitespace(line.charAt(i)))i++;setProperty(key,line.substring(i));}}
